// Formula cases for Glaze Sheets' engine, with Microsoft Excel as the oracle: scripts/sheet-excel-golden.js writes each
// family into its own workbook (test/fixtures/sheets/<family>.xlsx), Excel calculates and saves it, and golden.json keeps
// what Excel cached; test/sheet-golden.test.js holds the engine to it.
// A case: { id, family, sheet, cell, formula, inputs, note }. inputs maps 'Sheet!A1' to what the cell holds first: a
// number, a string (always text, even "5" or "1/2"), a boolean, null (left blank on purpose), { e: '#N/A' } (an error
// typed in) or { f: '=…' } (a formula). fill: the range one formula was filled over, which Excel saves as a shared
// formula; array: a legacy (Ctrl+Shift+Enter) array formula's range; unsupported: Excel's message when it refused the
// formula. Every other formula is entered as a dynamic-array formula and returns one value (no spills). Deterministic
// only: no NOW, TODAY, RAND, INFO, CELL, OFFSET or INDIRECT. Text and dates read as en-US, checked by the harness.

const colName = (c) => { let s = ''; for (; c > 0; c = Math.floor((c - 1) / 26)) s = String.fromCharCode(65 + ((c - 1) % 26)) + s; return s; };
const colNumber = (s) => [...s].reduce((n, ch) => n * 26 + ch.charCodeAt(0) - 64, 0);
// Values from a cell down a column, or a grid of rows from a top-left cell.
const block = (at, values) => {
  const [, sheet, col, row] = /^(.+)!([A-Z]+)(\d+)$/.exec(at);
  const out = {};
  (Array.isArray(values[0]) ? values : values.map((v) => [v])).forEach((line, i) => line.forEach((v, j) => {
    out[`${sheet}!${colName(colNumber(col) + j)}${+row + i}`] = v;
  }));
  return out;
};
const NA = { e: '#N/A' }, DIV0 = { e: '#DIV/0!' };

