const cases = [];
for (const [family, list] of Object.entries(ROWS)) {
  let row = 0;
  const count = {};
  for (const item of list) {
    const c = Array.isArray(item) ? { formula: item[0], uses: item[1], note: item[2] } : item;
    const fn = (/(?<![\w.])([A-Z][A-Z0-9]*(?:\.[A-Z0-9]+)*)\(/.exec(c.formula)?.[1] || 'op').toLowerCase();
    count[fn] = (count[fn] || 0) + 1;
    const inputs = {};
    for (const name of (c.uses || '').split(' ').filter(Boolean)) {
      if (!DATA[name]) throw Error(`cases.js: no data named ${name}`);
      Object.assign(inputs, DATA[name]);
    }
    Object.assign(inputs, c.inputs);
    cases.push({
      id: `${family}.${fn}.${count[fn]}`, family, sheet: c.sheet || 'Cases', cell: c.cell || `A${++row}`, formula: c.formula,
      inputs, note: c.note || '', ...(c.fill && { fill: c.fill }), ...(c.array && { array: c.array }), ...(c.unsupported != null && { unsupported: c.unsupported }),
    });
  }
}

module.exports = { cases, families, data: DATA };
